import { ChevronDownIcon } from 'lucide-react';
import { cn } from '../../utils';
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { SegmentedControl } from './segmented-control';

export type Interval =
  | '1s'
  | '1m'
  | '3m'
  | '5m'
  | '15m'
  | '30m'
  | '1H'
  | '2H'
  | '4H'
  | '1D'
  | '1W'
  | '1M';

export interface IntervalOption {
  value: Interval;
  label: string;
  /** Bar length in milliseconds — hand this to your feed. */
  ms: number;
  group: 'Seconds' | 'Minutes' | 'Hours' | 'Days';
}

export const INTERVALS: IntervalOption[] = [
  { value: '1s', label: '1s', ms: 1_000, group: 'Seconds' },
  { value: '1m', label: '1m', ms: 60_000, group: 'Minutes' },
  { value: '3m', label: '3m', ms: 180_000, group: 'Minutes' },
  { value: '5m', label: '5m', ms: 300_000, group: 'Minutes' },
  { value: '15m', label: '15m', ms: 900_000, group: 'Minutes' },
  { value: '30m', label: '30m', ms: 1_800_000, group: 'Minutes' },
  { value: '1H', label: '1H', ms: 3_600_000, group: 'Hours' },
  { value: '2H', label: '2H', ms: 7_200_000, group: 'Hours' },
  { value: '4H', label: '4H', ms: 14_400_000, group: 'Hours' },
  { value: '1D', label: '1D', ms: 86_400_000, group: 'Days' },
  { value: '1W', label: '1W', ms: 604_800_000, group: 'Days' },
  { value: '1M', label: '1M', ms: 2_592_000_000, group: 'Days' },
];

export function intervalMs(value: Interval): number {
  return INTERVALS.find((i) => i.value === value)?.ms ?? 60_000;
}

export interface IntervalPickerProps {
  value: Interval;
  onChange: (value: Interval) => void;
  /** Intervals promoted to always-visible buttons. */
  favorites?: Interval[];
  /** Offer the full grouped list in a dropdown beside the favorites. */
  showAll?: boolean;
  size?: 'sm' | 'default';
  className?: string;
}

/**
 * Chart timeframe selector.
 *
 * A desk uses three or four intervals constantly and the rest twice a month, so
 * the favorites stay one click away and everything else lives behind a grouped
 * dropdown. If the current interval is not a favorite it is promoted into the
 * row, so the control always shows what you are actually looking at rather than
 * hiding it inside a collapsed menu.
 */
export function IntervalPicker({
  value,
  onChange,
  favorites = ['1m', '5m', '15m', '1H', '1D'],
  showAll = true,
  size = 'sm',
  className,
}: IntervalPickerProps) {
  const visible = favorites.includes(value) ? favorites : [...favorites, value];
  const groups = Array.from(new Set(INTERVALS.map((i) => i.group)));

  return (
    <div className={cn('flex items-center gap-1.5', className)}>
      <SegmentedControl
        size={size}
        aria-label="Chart interval"
        value={value}
        onChange={(v) => onChange(v as Interval)}
        options={visible.map((v) => ({
          value: v,
          label: INTERVALS.find((i) => i.value === v)?.label ?? v,
        }))}
      />

      {showAll && (
        <Select value={value} onValueChange={(v) => onChange(v as Interval)}>
          {/* Chevron only: the active interval is already shown in the row
              beside this, so repeating it here would be the same fact twice.
              Radix still needs a SelectValue mounted to track selection. */}
          <SelectTrigger
            size="sm"
            aria-label="All intervals"
            className="h-6 w-7 justify-center px-0 [&>svg:last-child]:hidden"
          >
            <ChevronDownIcon className="size-3.5 shrink-0 opacity-70" />
            <span className="sr-only">
              <SelectValue />
            </span>
          </SelectTrigger>
          <SelectContent align="end">
            {groups.map((group) => (
              <SelectGroup key={group}>
                <SelectLabel>{group}</SelectLabel>
                {INTERVALS.filter((i) => i.group === group).map((i) => (
                  <SelectItem key={i.value} value={i.value} className="font-mono">
                    {i.label}
                  </SelectItem>
                ))}
              </SelectGroup>
            ))}
          </SelectContent>
        </Select>
      )}
    </div>
  );
}

import type { ReactNode } from 'react';
import { ToggleGroup, ToggleGroupItem } from '../ui/toggle-group';
import { cn } from '../../utils';

export interface SegmentOption<T extends string> {
  value: T;
  label: ReactNode;
  disabled?: boolean;
  /** Announced to screen readers when the label is an icon or abbreviation. */
  title?: string;
}

export interface SegmentedControlProps<T extends string> {
  options: ReadonlyArray<SegmentOption<T>>;
  value: T;
  onChange: (value: T) => void;
  /** `direction` tints a `buy` value green and a `sell` value red. */
  variant?: 'default' | 'direction';
  size?: 'sm' | 'default' | 'lg';
  block?: boolean;
  'aria-label'?: string;
  className?: string;
}

/**
 * Interval picker, side switch, order-type selector.
 *
 * Wraps Radix ToggleGroup in single-selection mode rather than hand-rolling a
 * radio group: roving tabindex, arrow-key navigation and the correct roles all
 * come from the primitive. The one behavior added on top is refusing to clear -
 * Radix lets a single toggle group deselect itself, and "no side selected" is
 * not a state an order ticket should ever be able to reach.
 */
export function SegmentedControl<T extends string>({
  options,
  value,
  onChange,
  variant = 'default',
  size = 'default',
  block = false,
  className,
  ...aria
}: SegmentedControlProps<T>) {
  return (
    <ToggleGroup
      type="single"
      value={value}
      onValueChange={(next) => {
        if (next) onChange(next as T);
      }}
      variant={variant}
      size={size}
      aria-label={aria['aria-label']}
      className={cn(block && 'flex w-full', className)}
    >
      {options.map((option) => (
        <ToggleGroupItem
          key={option.value}
          value={option.value}
          disabled={option.disabled}
          aria-label={option.title}
          title={option.title}
        >
          {option.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

import * as SelectPrimitive from '@radix-ui/react-select';
import { CheckIcon, ChevronDownIcon, ChevronUpIcon } from 'lucide-react';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/** Radix Select: typeahead, collision-aware positioning, full keyboard support. */
const Select = SelectPrimitive.Root;
const SelectGroup = SelectPrimitive.Group;
const SelectValue = SelectPrimitive.Value;

function SelectTrigger({
  className,
  size = 'default',
  children,
  ...props
}: ComponentProps<typeof SelectPrimitive.Trigger> & { size?: 'sm' | 'default' }) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        "border-input bg-background text-foreground flex w-fit cursor-pointer items-center justify-between gap-2 rounded-md border px-2.5 py-1 text-sm whitespace-nowrap shadow-xs transition-[color,box-shadow] outline-none data-[size=default]:h-9 data-[size=sm]:h-8 *:data-[slot=select-value]:flex *:data-[slot=select-value]:items-center *:data-[slot=select-value]:gap-2 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:opacity-50",
        'focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]',
        'disabled:cursor-not-allowed disabled:opacity-50',
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <ChevronDownIcon className="size-4 opacity-50" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}

function SelectContent({
  className,
  children,
  position = 'popper',
  ...props
}: ComponentProps<typeof SelectPrimitive.Content>) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        data-slot="select-content"
        className={cn(
          'bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 relative z-50 max-h-(--radix-select-content-available-height) min-w-32 origin-(--radix-select-content-transform-origin) overflow-x-hidden overflow-y-auto rounded-md border shadow-md',
          position === 'popper' &&
            'data-[side=bottom]:translate-y-1 data-[side=top]:-translate-y-1',
          className,
        )}
        position={position}
        {...props}
      >
        <SelectScrollUpButton />
        <SelectPrimitive.Viewport
          className={cn(
            'p-1',
            position === 'popper' &&
              'h-[var(--radix-select-trigger-height)] w-full min-w-[var(--radix-select-trigger-width)] scroll-my-1',
          )}
        >
          {children}
        </SelectPrimitive.Viewport>
        <SelectScrollDownButton />
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
}

function SelectLabel({ className, ...props }: ComponentProps<typeof SelectPrimitive.Label>) {
  return (
    <SelectPrimitive.Label
      data-slot="select-label"
      className={cn('text-muted-foreground px-2 py-1.5 text-xs', className)}
      {...props}
    />
  );
}

function SelectItem({
  className,
  children,
  ...props
}: ComponentProps<typeof SelectPrimitive.Item>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(
        "focus:bg-accent focus:text-accent-foreground relative flex w-full cursor-pointer items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-sm outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    >
      <span className="absolute right-2 flex size-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <CheckIcon className="size-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  );
}

function SelectSeparator({
  className,
  ...props
}: ComponentProps<typeof SelectPrimitive.Separator>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn('bg-border pointer-events-none -mx-1 my-1 h-px', className)}
      {...props}
    />
  );
}

function SelectScrollUpButton({
  className,
  ...props
}: ComponentProps<typeof SelectPrimitive.ScrollUpButton>) {
  return (
    <SelectPrimitive.ScrollUpButton
      data-slot="select-scroll-up-button"
      className={cn('flex cursor-default items-center justify-center py-1', className)}
      {...props}
    >
      <ChevronUpIcon className="size-4" />
    </SelectPrimitive.ScrollUpButton>
  );
}

function SelectScrollDownButton({
  className,
  ...props
}: ComponentProps<typeof SelectPrimitive.ScrollDownButton>) {
  return (
    <SelectPrimitive.ScrollDownButton
      data-slot="select-scroll-down-button"
      className={cn('flex cursor-default items-center justify-center py-1', className)}
      {...props}
    >
      <ChevronDownIcon className="size-4" />
    </SelectPrimitive.ScrollDownButton>
  );
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

import * as ToggleGroupPrimitive from '@radix-ui/react-toggle-group';
import { cva, type VariantProps } from 'class-variance-authority';
import { createContext, useContext, type ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Radix ToggleGroup, styled as a segmented control.
 *
 * Radix is doing the part that is easy to get wrong by hand: roving tabindex,
 * arrow-key navigation, and the right roles for single vs multiple selection.
 */
const toggleGroupItemVariants = cva(
  "inline-flex items-center justify-center gap-1 rounded-sm text-[11px] font-semibold tracking-wide whitespace-nowrap transition-colors outline-none cursor-pointer disabled:pointer-events-none disabled:opacity-50 focus-visible:ring-ring/50 focus-visible:ring-2 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        default:
          'text-muted-foreground hover:text-foreground data-[state=on]:bg-card data-[state=on]:text-foreground data-[state=on]:shadow-sm',
        direction:
          'text-muted-foreground hover:text-foreground data-[state=on]:shadow-sm data-[value=buy]:data-[state=on]:bg-up data-[value=buy]:data-[state=on]:text-up-foreground data-[value=sell]:data-[state=on]:bg-down data-[value=sell]:data-[state=on]:text-down-foreground',
      },
      size: {
        default: 'h-6 px-2.5',
        sm: 'h-5 px-2 text-[10px]',
        lg: 'h-8 px-3 text-xs',
      },
    },
    defaultVariants: { variant: 'default', size: 'default' },
  },
);

const ToggleGroupContext = createContext<VariantProps<typeof toggleGroupItemVariants>>({
  variant: 'default',
  size: 'default',
});

function ToggleGroup({
  className,
  variant,
  size,
  children,
  ...props
}: ComponentProps<typeof ToggleGroupPrimitive.Root> &
  VariantProps<typeof toggleGroupItemVariants>) {
  return (
    <ToggleGroupPrimitive.Root
      data-slot="toggle-group"
      data-variant={variant}
      data-size={size}
      className={cn(
        'bg-secondary/70 inline-flex w-fit items-center gap-0.5 rounded-md border p-0.5',
        'data-[orientation=vertical]:flex-col',
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive.Root>
  );
}

function ToggleGroupItem({
  className,
  children,
  variant,
  size,
  ...props
}: ComponentProps<typeof ToggleGroupPrimitive.Item> &
  VariantProps<typeof toggleGroupItemVariants>) {
  const context = useContext(ToggleGroupContext);
  return (
    <ToggleGroupPrimitive.Item
      data-slot="toggle-group-item"
      data-value={props.value}
      className={cn(
        toggleGroupItemVariants({
          variant: variant ?? context.variant,
          size: size ?? context.size,
        }),
        'min-w-0 flex-1',
        className,
      )}
      {...props}
    >
      {children}
    </ToggleGroupPrimitive.Item>
  );
}

export { ToggleGroup, ToggleGroupItem, toggleGroupItemVariants };

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
